/**
 * GDD §8 / §12 — the banner gate.
 *
 * A fresh commander arrives unaffiliated (`seedWorld` does this on purpose) and
 * the shell routes here before staging, because which banner you fight for
 * decides what "uncontested ground" even means. Two ways off the bench:
 *
 *   FOUND   — file a charter: name, tag, motto and a banner request.
 *   ENLIST  — join a guild already holding ground.
 *
 * No chrome, no dock, no skip. `app.ts` latches `view.onboarded` the moment the
 * commander appears on a roster, so this screen shows itself exactly once and
 * then never again — including for a player who later leaves their guild, or who
 * is wiped off the map and bounced back to staging.
 *
 * BANNER PICKER CONTRACT: the founder chooses from `BANNER_PRESETS`, not from
 * `GUILD_COLORS`. Those are different sets for a reason (see config/visual.ts) —
 * half of `GUILD_COLORS` is what the world seeder hands to RIVAL banners, and
 * `MockBackend.resolveBanner` only honours a request whose colour is a real
 * preset. Offering the wrong palette means the founder picks a colour and is
 * silently issued a different one. Presets already flying on the register are
 * shown struck through rather than hidden: "that one is taken" is information.
 */
import '../../styles/guild.css';
import '../../styles/onboarding.css';

import type { BannerRequest, IBackend } from '../../backend/IBackend';
import { GUILD } from '../../config/balance';
import { SEASON } from '../../config/balance';
import {
  BANNER_PRESETS,
  EMBLEM_COUNT,
  firstFreeBanner,
  isBannerDistinct,
  type BannerPreset,
} from '../../config/visual';
import { guildPower } from '../../game/guild/power';
import { guildTileCounts } from '../../game/world/season';
import { game } from '../../game/store';
import type { GameState, Guild } from '../../game/types';
import { badge, button, emptyState, guildSigil, ICONS, panel, toast } from '../components';
import { clear, cssHex, Disposer, el, fmtNum, haptic, rgba } from '../dom';
import type { Screen } from '../screen';

type Path = 'found' | 'enlist';

/** Synthetic guild, purely to drive the sigil preview. */
function previewGuild(name: string, tag: string, color: number, emblem: number): Guild {
  return {
    id: 'preview',
    name,
    tag,
    motto: '',
    color,
    leaderId: 'preview',
    memberIds: ['preview'],
    roles: { preview: 'leader' },
    diplomats: ['preview'],
    createdAt: 0,
    emblem,
  };
}

export function createOnboardingScreen(backend: IBackend): Screen {
  const root = el('div', { class: 'screen screen--flow onb' });

  // ── state ──────────────────────────────────────────────────────────────────
  let path: Path = 'found';
  let color = BANNER_PRESETS[0].color;
  let emblem = BANNER_PRESETS[0].emblem;
  /** Set once the founder touches the picker, so sync stops re-defaulting it. */
  let bannerTouched = false;
  let lastState: GameState | null = null;
  let filing = false;
  let registerKey = '';
  let takenKey = '';

  // ── header ─────────────────────────────────────────────────────────────────
  const seasonLine = el('div', { class: 'onb__season mono' });
  const head = el(
    'div',
    { class: 'onb__head' },
    el('div', { class: 'onb__eyebrow mono', text: 'PLANETFALL PENDING' }),
    el('h1', { class: 'onb__title display', text: 'RAISE A BANNER' }),
    el('p', {
      class: 'onb__lede',
      text: 'Every system in this war runs through a charter — intel, orders, logistics, diplomacy and the season itself. Choose the banner you fight under before you pick a landing site.',
    }),
    seasonLine,
  );

  // ── path switch ────────────────────────────────────────────────────────────
  const segFound = el('button', {
    class: 'onb-seg__btn is-on',
    attrs: { type: 'button' },
    text: 'FOUND A CHARTER',
  });
  const segEnlist = el('button', {
    class: 'onb-seg__btn',
    attrs: { type: 'button' },
    text: 'ENLIST',
  });
  const seg = el('div', { class: 'onb-seg', attrs: { role: 'tablist' } }, segFound, segEnlist);

  const setPath = (next: Path): void => {
    if (path === next) return;
    path = next;
    segFound.classList.toggle('is-on', next === 'found');
    segEnlist.classList.toggle('is-on', next === 'enlist');
    foundPane.classList.toggle('is-on', next === 'found');
    enlistPane.classList.toggle('is-on', next === 'enlist');
    haptic(9);
    if (lastState) sync(lastState);
  };
  segFound.addEventListener('click', () => setPath('found'));
  segEnlist.addEventListener('click', () => setPath('enlist'));

  // ── found: charter form ────────────────────────────────────────────────────
  const nameInput = el('input', {
    class: 'field__input',
    attrs: { type: 'text', maxlength: 28, placeholder: 'IRON COVENANT', autocomplete: 'off' },
  });
  const tagInput = el('input', {
    class: 'field__input',
    attrs: { type: 'text', maxlength: 5, placeholder: 'IRON', autocomplete: 'off', spellcheck: 'false' },
  });
  const mottoInput = el('input', {
    class: 'field__input',
    attrs: { type: 'text', maxlength: 64, placeholder: 'We hold what we take.', autocomplete: 'off' },
  });

  const sigilFrame = el('div', { class: 'onb-crest__frame' });
  const crestName = el('div', { class: 'onb-crest__name display', text: 'UNNAMED CHARTER' });
  const crestTag = el('span', { class: 'ghead__tag', text: '——' });
  const crestMotto = el('div', { class: 'onb-crest__motto', text: 'no motto filed' });
  const crest = el(
    'div',
    { class: 'onb-crest' },
    sigilFrame,
    el(
      'div',
      { class: 'grow' },
      crestName,
      el('div', { class: 'ghead__tagline' }, crestTag),
      crestMotto,
    ),
  );

  const bannerRow = el('div', { class: 'onb-banners' });
  const emblemRow = el('div', { class: 'onb-emblems' });
  const verdict = el('div', { class: 'tfverdict', text: 'ENTER A NAME AND A TAG' });

  const fileBtn = button('FILE THE CHARTER', {
    variant: 'primary',
    wide: true,
    icon: ICONS.check,
    onClick: () => void fileCharter(),
  });

  const foundPane = el(
    'div',
    { class: 'onb-pane is-on' },
    panel(
      { title: 'FOUND A CHARTER', subtitle: 'raise your own banner', accent: 'var(--cyan)', holo: true },
      crest,
      el(
        'div',
        { class: 'field selectable' },
        el('span', { class: 'field__label', text: 'GUILD NAME' }),
        nameInput,
      ),
      el(
        'div',
        { class: 'field selectable' },
        el('span', { class: 'field__label', text: 'TAG · 2–5 CHARACTERS' }),
        tagInput,
      ),
      el(
        'div',
        { class: 'field selectable' },
        el('span', { class: 'field__label', text: 'MOTTO' }),
        mottoInput,
      ),
      el('div', { class: 'onb-sec mono', text: 'BANNER' }),
      bannerRow,
      el('div', { class: 'onb-sec mono', text: 'EMBLEM' }),
      emblemRow,
      verdict,
      fileBtn,
    ),
  );

  // ── enlist: the register ───────────────────────────────────────────────────
  const registerList = el('div', { class: 'col' });
  const enlistPane = el(
    'div',
    { class: 'onb-pane' },
    panel(
      { title: 'ACTIVE REGISTER', subtitle: 'banners already holding ground', accent: 'var(--gold)' },
      registerList,
    ),
  );

  const body = el('div', { class: 'onb__body' }, foundPane, enlistPane);
  const foot = el('div', {
    class: 'onb__foot mono',
    text: 'ONE-TIME DECISION · YOU MAY LEAVE OR TRANSFER LATER FROM THE GUILD PANEL',
  });

  root.appendChild(head);
  root.appendChild(seg);
  root.appendChild(body);
  root.appendChild(foot);

  // ── banner picker ──────────────────────────────────────────────────────────

  /** Every banner colour currently on the register. */
  function takenColors(state: GameState): number[] {
    return Object.values(state.guilds).map((g) => g.color);
  }

  function renderBanners(state: GameState): void {
    const taken = takenColors(state);
    // If nothing is free the register is saturated, so refusing every preset
    // would be a dead end. Let the founder pick and let the registry reallocate.
    const anyFree = BANNER_PRESETS.some((p) => isBannerDistinct(p.color, taken));

    const key = `${taken.slice().sort((a, b) => a - b).join(',')}|${color}|${emblem}`;
    if (key === takenKey) return;
    takenKey = key;

    clear(bannerRow);
    for (const preset of BANNER_PRESETS) {
      const free = isBannerDistinct(preset.color, taken);
      const blocked = anyFree && !free;
      const btn = el('button', {
        class: `onb-banner${preset.color === color ? ' is-on' : ''}${blocked ? ' is-taken' : ''}`,
        style: `--band:${cssHex(preset.color)};--band-soft:${rgba(preset.color, 0.2)}`,
        attrs: { type: 'button', disabled: blocked },
        aria: { label: `${preset.label}${blocked ? ' — already flying' : ''}` },
      });
      btn.appendChild(el('i', { class: 'onb-banner__swatch', aria: { hidden: 'true' } }));
      btn.appendChild(el('span', { class: 'onb-banner__label mono', text: preset.label }));
      if (blocked) btn.appendChild(el('span', { class: 'onb-banner__note mono', text: 'FLYING' }));
      btn.addEventListener('click', () => pick(preset));
      bannerRow.appendChild(btn);
    }

    clear(emblemRow);
    for (let i = 0; i < EMBLEM_COUNT; i++) {
      const index = i;
      const btn = el('button', {
        class: `onb-emblem${i === emblem ? ' is-on' : ''}`,
        attrs: { type: 'button' },
        aria: { label: `emblem ${index + 1}` },
      });
      btn.appendChild(guildSigil(previewGuild('', '', color, index), 30));
      btn.addEventListener('click', () => {
        emblem = index;
        bannerTouched = true;
        haptic(9);
        takenKey = '';
        repaint();
        if (lastState) renderBanners(lastState);
      });
      emblemRow.appendChild(btn);
    }
  }

  function pick(preset: BannerPreset): void {
    color = preset.color;
    // A preset arrives with its own emblem; respect a deliberate choice already
    // made, otherwise take the one the preset ships with.
    if (!bannerTouched) emblem = preset.emblem;
    bannerTouched = true;
    haptic(9);
    takenKey = '';
    repaint();
    if (lastState) renderBanners(lastState);
  }

  function repaint(): void {
    const name = nameInput.value.trim();
    const tag = tagInput.value.trim().toUpperCase();
    const motto = mottoInput.value.trim();

    crestName.textContent = name.length > 0 ? name.toUpperCase() : 'UNNAMED CHARTER';
    crestTag.textContent = tag.length > 0 ? tag : '——';
    crestMotto.textContent = motto.length > 0 ? motto : 'no motto filed';

    crest.style.setProperty('--band', cssHex(color));
    crest.style.setProperty('--band-soft', rgba(color, 0.22));
    crestTag.style.color = cssHex(color);
    crestTag.style.borderColor = cssHex(color);

    clear(sigilFrame);
    sigilFrame.appendChild(guildSigil(previewGuild(name, tag, color, emblem), 62));
  }

  /**
   * A charter needs a 2–5 character tag because the roster, chat, leaderboard
   * and every army token render it — but the player was only asked for a name
   * and a colour, so make them a tag instead of demanding one. Two words give
   * their leading pairs ("CRIMSON PACT" → CRPA); one word gives its first four
   * ("IRONVEIL" → IRON).
   */
  function deriveTag(name: string): string {
    const words = name.toUpperCase().replace(/[^A-Z0-9 ]/g, '').split(/\s+/).filter(Boolean);
    if (words.length === 0) return '';
    const raw =
      words.length >= 2 ? words[0].slice(0, 2) + words[1].slice(0, 2) : words[0].slice(0, 4);
    return raw.slice(0, 5);
  }

  // Once the commander types their own tag it is theirs; clearing the field
  // hands control back to the deriver rather than stranding them on empty.
  let tagTouched = false;

  for (const input of [nameInput, tagInput, mottoInput]) {
    input.addEventListener('input', () => {
      if (input === tagInput) {
        tagInput.value = tagInput.value.toUpperCase().replace(/[^A-Z0-9]/g, '');
        tagTouched = tagInput.value.length > 0;
      }
      if (input === nameInput && !tagTouched) {
        tagInput.value = deriveTag(nameInput.value);
      }
      repaint();
      if (lastState) applyVerdict(lastState);
    });
  }

  // ── validation ─────────────────────────────────────────────────────────────
  function validate(state: GameState): string | null {
    const name = nameInput.value.trim();
    const tag = tagInput.value.trim().toUpperCase();
    if (name.length < 2) return 'guild name too short';
    if (tag.length < 2 || tag.length > 5) return 'guild tag must be 2-5 characters';
    const clash = Object.values(state.guilds).some(
      (g) => g.tag.toUpperCase() === tag || g.name.toLowerCase() === name.toLowerCase(),
    );
    if (clash) return 'that name or tag is already flying';
    return null;
  }

  function applyVerdict(state: GameState): void {
    const problem = validate(state);
    if (problem) {
      verdict.className = 'tfverdict is-bad';
      verdict.textContent = problem.toUpperCase();
      fileBtn.disabled = true;
      return;
    }
    verdict.className = 'tfverdict is-ok';
    verdict.textContent = 'CHARTER READY TO FILE';
    fileBtn.disabled = filing;
  }

  async function fileCharter(): Promise<void> {
    const state = lastState;
    if (!state || filing) return;
    const problem = validate(state);
    if (problem) {
      toast({ title: 'REJECTED', body: problem, kind: 'bad' });
      return;
    }

    filing = true;
    fileBtn.disabled = true;
    const requested: BannerRequest = { color, emblem };
    try {
      const res = await backend.createGuild(
        nameInput.value.trim(),
        tagInput.value.trim().toUpperCase(),
        mottoInput.value.trim(),
        requested,
      );
      if (!res.ok) {
        toast({ title: 'CHARTER REFUSED', body: res.error, kind: 'bad' });
        return;
      }
      const issued = backend.getState().guilds[res.value];
      if (issued && (issued.color !== requested.color || issued.emblem !== requested.emblem)) {
        // Honest about it rather than silent: the registry keeps every banner
        // tellable apart on a hex token, and that outranks the request.
        toast({
          title: 'BANNER REALLOCATED',
          body: 'The registry issued a different mark so no two banners read alike.',
          kind: 'info',
        });
      } else {
        toast({ title: 'CHARTER FILED', kind: 'ok' });
      }
      haptic([12, 30, 18]);
      // The shell latches `onboarded` off the roster change and routes onward.
    } finally {
      filing = false;
      if (lastState) applyVerdict(lastState);
    }
  }

  // ── register ───────────────────────────────────────────────────────────────
  function renderRegister(state: GameState): void {
    const tiles = guildTileCounts(state);
    const guilds = Object.values(state.guilds).sort(
      (a, b) => (tiles[b.id] ?? 0) - (tiles[a.id] ?? 0) || a.name.localeCompare(b.name),
    );

    const key = guilds.map((g) => `${g.id}:${g.memberIds.length}:${tiles[g.id] ?? 0}`).join('|');
    if (key === registerKey) return;
    registerKey = key;

    clear(registerList);
    if (guilds.length === 0) {
      registerList.appendChild(emptyState('◇', 'no banners on the register yet — found the first'));
      return;
    }

    for (const guild of guilds) {
      const full = guild.memberIds.length >= GUILD.maxMembers;
      const power = guildPower(state, guild.id);
      const online = guild.memberIds.reduce((n, id) => n + (state.players[id]?.online ? 1 : 0), 0);
      const row = el('div', { class: 'gitem', style: `--band:${cssHex(guild.color)}` });

      const sig = el('div', { class: 'dir__sig' });
      sig.appendChild(guildSigil(guild, 34));
      row.appendChild(sig);

      const id = el('div', { class: 'gitem__id' });
      id.appendChild(
        el(
          'div',
          { class: 'row', style: 'gap:6px' },
          el('span', { class: 'gitem__name grow', text: guild.name }),
          el('span', {
            class: 'ghead__tag',
            style: `color:${cssHex(guild.color)};border-color:${cssHex(guild.color)}`,
            text: guild.tag,
          }),
        ),
      );
      if (guild.motto) id.appendChild(el('div', { class: 'gitem__motto', text: guild.motto }));
      id.appendChild(
        el(
          'div',
          { class: 'gitem__stats' },
          el('span', { text: `${guild.memberIds.length}/${GUILD.maxMembers} CMDR` }),
          el('span', { text: `${online} ONLINE` }),
          el('span', { text: `${tiles[guild.id] ?? 0} TILES` }),
          el('span', { text: `${fmtNum(power.total)} PWR` }),
        ),
      );
      row.appendChild(id);

      if (full) {
        row.appendChild(badge('FULL', 'bad'));
      } else {
        row.appendChild(
          button('ENLIST', {
            variant: 'ghost',
            small: true,
            onClick: () => {
              void (async () => {
                const res = await backend.joinGuild(guild.id);
                if (!res.ok) {
                  toast({ title: 'REFUSED', body: res.error, kind: 'bad' });
                  return;
                }
                toast({ title: 'ENLISTED', body: guild.name, kind: 'ok' });
                haptic([12, 30, 18]);
              })();
            },
          }),
        );
      }
      registerList.appendChild(row);
    }
  }

  // ── season strip ───────────────────────────────────────────────────────────
  function renderSeason(state: GameState): void {
    const week = Math.floor((state.now - state.season.startedAt) / SEASON.rotationMs) + 1;
    const weeks = Math.max(1, Math.round(SEASON.lengthMs / SEASON.rotationMs));
    const open = Object.values(state.world.sectors).filter((s) => s.state === 'active').length;
    const banners = Object.keys(state.guilds).length;
    clear(seasonLine);
    for (const bit of [
      state.season.name.toUpperCase(),
      `WEEK ${Math.min(week, weeks)} OF ${weeks}`,
      `${banners} BANNER${banners === 1 ? '' : 'S'}`,
      `${open} SECTOR${open === 1 ? '' : 'S'} OPEN`,
    ]) {
      seasonLine.appendChild(el('span', { text: bit }));
    }
  }

  // ── lifecycle ──────────────────────────────────────────────────────────────
  const disposer = new Disposer();

  function sync(state: GameState | null): void {
    if (!state) return;
    lastState = state;
    renderSeason(state);

    // Default the request to the first mark nobody is flying, until the founder
    // touches the picker themselves.
    if (!bannerTouched) {
      const free = firstFreeBanner(takenColors(state)) ?? BANNER_PRESETS[0];
      if (free.color !== color) {
        color = free.color;
        emblem = free.emblem;
        takenKey = '';
      }
    }

    if (path === 'found') {
      repaint();
      renderBanners(state);
      applyVerdict(state);
    } else {
      renderRegister(state);
    }
  }

  return {
    el: root,

    mount(): void {
      disposer.add(game.subscribe((state) => sync(state)));
      sync(game.get());
    },

    unmount(): void {
      disposer.dispose();
      lastState = null;
      registerKey = '';
      takenKey = '';
    },
  };
}
